// Nodo Code: Validador de Respuesta del Agente
const mensaje = $json.mensaje;

// Validar si el mensaje existe y es válido
if (!mensaje || 
    mensaje === "" || 
    mensaje === null || 
    mensaje === undefined ||
    mensaje.includes("Agent stop") ||
    mensaje.includes("Unexpected token") ||
    mensaje.includes("not valid JSON") ||
    mensaje.length < 5) {

  // Respuesta de error amigable al usuario
  return [{
    json: {
      mensaje: "Disculpa, estoy procesando tu mensaje. Dame un momento para responderte correctamente.",
      phone: $json.phone,
      error: true,
      error_type: "agente_failed"
    }
  }];
}

// Si el mensaje es válido, continuar normalmente
return [{
  json: {
    mensaje: mensaje,
    phone: $json.phone,
    error: false
  }
}];

