const outputItems = [];

// Iteramos sobre cada item que llega al nodo
for (const item of items) {
  // Obtenemos todos los valores del objeto JSON del item actual
  const values = Object.values(item.json);

  // --- LÓGICA CORREGIDA Y MÁS FIABLE ---

  // 1. Contamos cuántos campos SON NULOS.
  const nullCount = values.filter(value => value === null).length;

  // 2. Establecemos tu regla: si hay 4 o más nulos, el formulario NO está relleno.
  const umbralDeNulos = 4;

  // 3. Comparamos y asignamos el valor correcto.
  if (nullCount >= umbralDeNulos) {
    item.json.formulario_rellenado = "no";
  } else {
    item.json.formulario_rellenado = "si";
  }

  // Añadimos el item modificado al array de salida
  outputItems.push(item);
}

// Devolvemos todos los items procesados para que el flujo continúe
return outputItems;

