// --- CEREBRO DE CONTEXTO PARA NUEVOS CONTACTOS (v2.0) ---
// Este nodo genera un contexto dinámico y estratégico para el agente de IA
// cuando interactúa con un usuario que aún no ha sido cualificado.

const items = $input.all();
const outputs = [];

for (const item of items) {
  const json = item.json;
  let outputData = {};

  // Solo se ejecuta esta lógica si el formulario NO está relleno.
  if (json.formulario_rellenado === 'no') {

    // --- 1. ANÁLISIS TEMPORAL: ¿Cuál es el ritmo de la conversación? ---
    // Mantenemos la lógica anterior porque es excelente para dar contexto sobre el timing.
    let contexto_temporal = "Primer contacto. Pendiente de cualificar.";
    try {
      if (json.fecha_mensaje) {
        const ahora = new Date();
        const fechaUltimoMensaje = new Date(json.fecha_mensaje);
        const minutosTranscurridos = (ahora.getTime() - fechaUltimoMensaje.getTime()) / (1000 * 60);

        if (minutosTranscurridos <= 15) {
          contexto_temporal = "Diálogo inicial en curso. El cliente está activo ahora.";
        } else if (minutosTranscurridos <= 120) {
          contexto_temporal = "Pausa reciente en la conversación. El cliente contestó hace poco.";
        } else if (minutosTranscurridos <= 1440) {
          contexto_temporal = "Retomando contacto tras unas horas.";
        } else {
          contexto_temporal = "Reactivando conversación tras un largo periodo de inactividad.";
        }
      }
    } catch (error) {
      // Fallback en caso de error con las fechas.
      contexto_temporal = "Primer contacto. No se pudo determinar el tiempo de respuesta.";
    }

    // --- 2. CONTEXTO ACTUAL: ¿Qué acaba de decir el cliente? ---
    // Hacemos más robusta la captura de su último mensaje.
    let ultimoMensajeCliente = "El cliente ha iniciado la conversación.";
    try {
       // El input 'response' contiene los últimos mensajes del usuario en un array JSON.
       const mensajes = JSON.parse(json.response);
       if (Array.isArray(mensajes) && mensajes.length > 0) {
         // Unimos todos los mensajes por si el cliente escribió rápido varias veces.
         ultimoMensajeCliente = mensajes.join(' ');
       }
    } catch (e) {
      // Si el formato falla, usamos el valor crudo como fallback.
      ultimoMensajeCliente = json.response || "No se pudo interpretar el mensaje.";
    }
    const contexto_actual = `El cliente acaba de enviar: \"${ultimoMensajeCliente}\".`;

    // --- 3. CONTEXTO GENERAL: ¿Cuál es el panorama completo? ---
    const contexto_general = `Estado: Contacto NUEVO, sin cualificar (Tel: ${json.telefono}). Aún no disponemos de datos clave (nombre, empresa, necesidades). El formulario NO ha sido rellenado.`;

    // --- 4. OPORTUNIDADES CLAVE (MEJORA PRINCIPAL): ¿Cuál es la estrategia a seguir? ---
    // Esta es la nueva directiva estratégica para el agente.
    const oportunidades_clave = `OBJETIVO PRINCIPAL: Iniciar una conversación de valor, NO CUALIFICAR.
    1. **VALIDAR Y RESPONDER:** Tu primera acción debe ser responder directamente al último mensaje del cliente para que se sienta escuchado y entendido.
    2. **PREGUNTAR PARA EXPLORAR:** Realiza una pregunta abierta e inteligente que le invite a explicar su 'dolor' o necesidad. Ejemplos: 'Claro, ¿qué proceso actual te gustaría mejorar?' o 'Entendido, ¿cuál es el mayor desafío que enfrentas en tu gestión diaria?'.
    3. **MISIÓN:** Tu misión es generar confianza y demostrar expertise. NO debes mencionar el formulario ni proponer una reunión todavía. Construye la relación primero.`;

    outputData = {
      contexto_temporal,
      contexto_actual,
      contexto_general,
      oportunidades_clave,
      // Pasamos los demás campos por si son necesarios
      formulario_rellenado: json.formulario_rellenado,
      response: json.response,
      phone: json.phone
    };

  } else {
    // Fallback: Si por alguna razón llega aquí un contacto ya cualificado,
    // simplemente pasamos sus datos sin modificarlos.
    outputData = item.json;
  }

  outputs.push({ json: outputData });
}

return outputs;

// --- CEREBRO DE CONTEXTO PARA CONTACTOS CUALIFICADOS (v2.0) ---
// Este nodo genera un briefing de misión para el agente de IA,
// basado en los datos que el cliente ha proporcionado en el formulario.

const items = $input.all();
const outputs = [];

for (const item of items) {
  // Hacemos una copia del JSON original para no perder ningún dato.
  const input = { ...item.json };
  let newContext = {};

  // --- 1. ANÁLISIS TEMPORAL: ¿Cuál es el ritmo de la conversación? ---
  // Esta lógica es sólida, la refinamos ligeramente para mayor claridad.
  let contexto_temporal = "Conversación con cliente cualificado.";
  try {
    if (input.fecha_mensaje) {
      const ahora = new Date();
      const fechaUltimoMensaje = new Date(input.fecha_mensaje);
      const minutosTranscurridos = (ahora.getTime() - fechaUltimoMensaje.getTime()) / (1000 * 60);

      if (minutosTranscurridos <= 15) {
        contexto_temporal = "Conversación fluida con cliente cualificado.";
      } else if (minutosTranscurridos <= 120) {
        contexto_temporal = "Pausa reciente en el diálogo.";
      } else {
        contexto_temporal = "Retomando la conversación tras un periodo de inactividad.";
      }
    }
  } catch (error) {
    contexto_temporal = "No se pudo determinar el ritmo de la conversación.";
  }

  // --- 2. CONTEXTO ACTUAL: ¿Qué acaba de decir el cliente? ---
  let ultimoMensajeCliente = "No se pudo interpretar el último mensaje.";
  try {
    const mensajes = JSON.parse(input.response);
    if (Array.isArray(mensajes) && mensajes.length > 0) {
      ultimoMensajeCliente = mensajes.join(' ');
    }
  } catch (e) {
    ultimoMensajeCliente = input.response || "No se pudo interpretar el mensaje.";
  }
  const nombreCliente = input.nombre_contacto || "El cliente";
  const contexto_actual = `Último mensaje de ${nombreCliente}: \"${ultimoMensajeCliente}\". Se espera tu respuesta como Iván.`;

  // --- 3. CONTEXTO GENERAL: Construcción dinámica a prueba de errores ---
  // Creamos el resumen pieza por pieza para evitar textos extraños si faltan datos.
  const generalParts = [];
  if (input.nombre_contacto) generalParts.push(`Cliente: ${input.nombre_contacto}`);
  if (input.nombre_empresa) generalParts.push(`de ${input.nombre_empresa}`);
  if (input.nicho_empresa) generalParts.push(`(${input.nicho_empresa}).`);
  if (input.problema_prioritario) generalParts.push(`Su problema prioritario es '${input.problema_prioritario}'.`);
  if (input.problemas_principales && input.problemas_principales !== input.problema_prioritario) {
    generalParts.push(`También mencionó: '${input.problemas_principales}'.`);
  }
  generalParts.push("Ha mostrado interés en invertir en automatización.");

  let contexto_general = generalParts.join(' ');
  // Mantenemos la memoria de acciones clave (si el calendario ya se envió).
  const calendarioYaEnviado = input.contexto_general && input.contexto_general.includes('[CALENDARIO_ENVIADO]');
  contexto_general += " [FORMULARIO_ENVIADO]" + (calendarioYaEnviado ? " [CALENDARIO_ENVIADO]" : "");


  // --- 4. OPORTUNIDADES CLAVE (MEJORA PRINCIPAL): El plan de acción ---
  let oportunidades_clave = "";
  if (calendarioYaEnviado) {
    oportunidades_clave = `MISIÓN: CERRAR LA REUNIÓN. El enlace del calendario ya fue enviado.
    1. **ACCIÓN:** Confirma si pudo agendar la reunión. Pregunta amablemente si tuvo algún problema para encontrar un hueco.
    2. **SI HAY DUDAS:** Resuelve cualquier última pregunta para darle total confianza.
    3. **REGLA:** NO vuelvas a enviar el enlace del calendario a menos que lo pida explícitamente.`;
  } else {
    oportunidades_clave = `MISIÓN: CONSEGUIR LA REUNIÓN.
    1. **ESTRATEGIA:** Conecta nuestra solución directamente con su problema prioritario: '${input.problema_prioritario}'. Tu objetivo es que el cliente piense 'esto es exactamente lo que necesito'.
    2. **TÁCTICA:** No listes características. Haz preguntas de sondeo que le hagan reflexionar sobre el coste de su problema (Ej: 'Sobre [su problema], ¿cuántas horas estimas que se pierden a la semana en tu equipo?'). Demuestra empatía y luego presenta la solución.
    3. **OPORTUNIDADES SECUNDARIAS:** Revisa sus 'otros problemas': '${input.problemas_principales}'. Si la conversación fluye, puedes mencionar de pasada cómo también atacamos uno de esos puntos.
    4. **OBJETIVO FINAL:** Cuando el cliente valide la solución o muestre claro interés, propón la reunión como el siguiente paso lógico y envía el enlace de Cal.com.`;
  }

  // Ensamblamos el nuevo contexto que sobreescribirá el anterior.
  newContext = {
    contexto_temporal,
    contexto_actual,
    contexto_general,
    oportunidades_clave
  };

  // Devolvemos el objeto original con los campos de contexto actualizados.
  outputs.push({ json: { ...input, ...newContext } });
}

return outputs;
